<script setup lang="ts">
import {computed,ref,onMounted} from 'vue';
const props=defineProps<{title:string;lines:string[]}>(),emit=defineEmits<{close:[]}>();
const dialog=ref<HTMLDialogElement|null>(null),notice=ref(''),busy=ref(false),image=ref(false);
const text=computed(()=>['Judibas | Focus To Do',props.title,...props.lines].join('\n'));
onMounted(()=>dialog.value?.showModal());
async function copy(){try{await navigator.clipboard.writeText(text.value);notice.value='Copied. Paste it into the conversation you choose.';}catch{notice.value='Select the preview text and copy it manually.';}}
function whatsapp(){if(text.value.length>8000){notice.value='This summary is too long for a WhatsApp link. Copy the text or download a card instead.';return;}window.open('https://wa.me/?text='+encodeURIComponent(text.value),'_blank','noopener,noreferrer');}
async function card():Promise<File>{const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d')!;canvas.width=1000;ctx.font='26px sans-serif';const rows:string[]=[];for(const line of [props.title,'',...props.lines]){let row='';for(const word of line.split(' ')){if(ctx.measureText(row+word).width>840){rows.push(row.trim());row='';}row+=word+' ';}rows.push(row.trim());}if(rows.length>140)rows.splice(139,rows.length-139,'More details are available in the text preview.');canvas.height=190+rows.length*40;ctx.fillStyle='#f8f7ff';ctx.fillRect(0,0,1000,canvas.height);ctx.fillStyle='#7762ee';ctx.fillRect(0,0,1000,12);ctx.font='bold 23px sans-serif';ctx.fillText('JUDIBAS / FOCUS TO DO',70,72);ctx.fillStyle='#242136';ctx.font='26px sans-serif';rows.forEach((line,i)=>ctx.fillText(line,70,135+i*40));ctx.font='18px sans-serif';ctx.fillStyle='#706c82';ctx.fillText('Shared snapshot | '+new Date().toLocaleDateString(),70,canvas.height-24);const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Unable to prepare image.')),'image/png'));return new File([blob],filename()+'.png',{type:'image/png'});}
function filename(){return 'judibas-focus-'+(props.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,65)||'summary');}
async function download(){busy.value=true;try{const file=await card(),url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value='Card downloaded. You can attach it in WhatsApp.';}catch(e:any){notice.value=e.message;}finally{busy.value=false;}}
async function share(){if(!navigator.share){notice.value='Native sharing is unavailable here. Use WhatsApp, Copy or Download card.';return;}busy.value=true;try{if(image.value){const file=await card();if(!navigator.canShare?.({files:[file]})){notice.value='This browser cannot share images directly. Download the card instead.';return;}await navigator.share({files:[file],title:props.title});}else await navigator.share({title:props.title,text:text.value});}catch(e:any){if(e.name!=='AbortError')notice.value='Sharing could not open. Try WhatsApp or Copy instead.';}finally{busy.value=false;}}
</script>
<template><dialog ref="dialog" class="ft-dialog ft-share-dialog" @cancel.prevent="!busy&&emit('close')"><header><div><p class="ft-eyebrow">SHARE A SNAPSHOT</p><h2>{{title}}</h2></div><button aria-label="Close share" :disabled="busy" @click="emit('close')">&times;</button></header><div class="ft-dialog-body"><p class="ft-muted">Review what will be shared. This sends a summary, without granting access to your workspace.</p><textarea class="ft-share-preview" :value="text" readonly rows="10" aria-label="Share preview"></textarea><label class="ft-check"><input v-model="image" type="checkbox">Share as an image through the device share menu</label><p v-if="notice" role="status">{{notice}}</p><div class="ft-share-actions"><button class="ft-primary" :disabled="busy" @click="share">Share...</button><button :disabled="busy" @click="whatsapp">WhatsApp</button><button :disabled="busy" @click="copy">Copy text</button><button :disabled="busy" @click="download">{{busy?'Preparing...':'Download card'}}</button></div></div></dialog></template>
